$string['panel_google_steps_form'] = 'Open the Google form and, in the ⋮ menu, choose “Apps Script”.
Delete what is there and paste this script.
Save and press “Run” once with the function “eguaheInstall”; accept the permissions it asks for.
From then on, each new answer comes into the inbox by itself.';
$string['panel_google_steps_sheet'] = 'Open the Google sheet the contacts come to and, in “Extensions”, choose “Apps Script”.
Delete what is there and paste this script.
Save and press “Run” once with the function “eguaheInstall”; accept the permissions it asks for.
Every ten minutes it sends the new rows; those already sent are not repeated.';
