$string['privacy_ai'] = 'You always talk to people of the centre. The centre does not use artificial intelligence with your data.';
$string['privacy_ai_on'] = 'You always talk to people of the centre. The team uses artificial intelligence to prepare draft answers and to sum up where each family is: what it is sent has no emails, phones or links, a person reviews and sends each message, and it is never used to decide anything about your family or to rate it.';
$string['privacy_ai_provider'] = 'Provider: {$a}.';
$string['privacy_ai_title'] = 'Artificial intelligence';
$string['privacy_basis'] = 'Your own request, to answer it; and your consent, for the channels you tick, which you can withdraw whenever you want.';
$string['privacy_basis_self'] = 'Your own request, to answer it; and your consent, for the channels you tick, which you can withdraw whenever you want.';
$string['privacy_basis_title'] = 'On what basis';
$string['privacy_keep'] = 'Up to {$a->months} months without activity. If your children enrol, while they study at the centre; when the last one leaves, another {$a->months} months without activity, and then it is erased by itself.';
$string['privacy_keep_title'] = 'How long';
$string['privacy_measure'] = 'Your page counts, only for the centre, when you open it, how far you get and what you touch (the calendar, the drawing, the story…); in the emails, which links you click, never whether you open them. No advertising cookies and no third-party tools. It is to know what you find useful, never to rate your family.';
$string['privacy_measure_title'] = 'What your page counts';
$string['privacy_rights'] = 'From your page you can download your data or erase it whenever you want. You can also ask for access, rectification, restriction or objection, and complain to the data protection authority.';
$string['privacy_rights_self'] = 'From your page you can download your data or erase it whenever you want. You can also ask for access, rectification, restriction or objection, and complain to the data protection authority.';
$string['privacy_rights_title'] = 'Your rights';
$string['privacy_what'] = 'Your name and how to reach you; the name of who would study, what you call them at home and the course. If you say so: where you live, how you heard of the centre, the date of birth, brothers and sisters who would come later, what you like to do in your free time, your children’s drawing, your answers to the centre’s questions and whether your children carry on next year. And what you write to the centre and the channels you allow.';
$string['privacy_what_self'] = 'Your name, how to reach you and what you would like to study. If you say so: where you live, how you heard of the centre, your date of birth, what you like to do in your free time, your answers to the centre\'s questions and whether you carry on next year. And what you write to the centre and the channels you allow.';
$string['privacy_what_title'] = 'Which data';
$string['privacy_who'] = '{$a->centre} is responsible for the data you give when you ask for information or a place.';
$string['privacy_who_dpo'] = 'Its data protection officer: {$a->dpo}.';
$string['privacy_who_title'] = 'Who is responsible';
$string['privacy_whom'] = 'Nobody outside the centre, unless the law requires it. The provider of the platform processes it on behalf of the centre and only for it. The centre never sells it nor puts a mark on any family.';
$string['privacy_whom_ai'] = 'The centre’s artificial intelligence provider receives the text of the messages, without emails, phones or links, to prepare the drafts.';
$string['privacy_whom_messaging'] = 'If you join by WhatsApp or Telegram from your page, the notices go through Meta or Telegram.';
$string['privacy_whom_title'] = 'Who else sees it';
$string['privacy_whom_voices'] = 'So that the first-day story says your child’s name, that name, and nothing else, goes to Oksigenia’s voice service, which records the reading.';
$string['privacy_why'] = 'To answer your questions, organise your visits and open days and, if you wish, your admission. And to know, with numbers that never name anyone, how the campaign is going.';
$string['privacy_why_self'] = 'To answer your questions, organise your visits and open days and, if you wish, your admission. And to know, with numbers that never name anyone, how the campaign is going.';
